// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzz parameters: an address 'from', a bool shouldFail to control callee behaviour,
    // and a uint8 len to choose how many recipients (keeps domain wide)
    function testFuzz_property(address from, bool shouldFail, uint8 len) public {
        // admissible domain: length > 0 and not too large to keep test lightweight
        vm.assume(len > 0 && len <= 5);

        // build recipient array of length 'len' all pointing to a helper callee
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);

        // deploy a helper that either reverts or succeeds depending on shouldFail
        ReverterOrRecorder helper = new ReverterOrRecorder(shouldFail);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
            vals[i] = uint256(i + 1);
        }

        // Call transfer and observe whether it returned (ok==true) or reverted (ok==false)
        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): The reference C never returns false; every call either
        // returns true (ok == true) when all callees succeed, or reverts (ok == false) when any callee fails.
        // We assert that ok implies the call returned true (i.e. ok==true). This is tautological in the test,
        // but the intended distinguishing condition is: when the helper is set to revert (shouldFail==true),
        // the reference must revert (ok==false). The mutant would instead return false (ok==true but returned false),
        // so we assert that if the helper is set to fail then the invocation does not complete successfully (ok == false).
        if (shouldFail) {
            // for the correct contract, any failing external call causes revert, so ok must be false
            assertTrue(!ok);
        } else {
            // when helper does not fail, all external calls succeed and the reference returns true, so ok must be true
            assertTrue(ok);
        }
    }
}

// Helper that either reverts on the target selector or records calls (and succeeds)
contract ReverterOrRecorder {
    bool public shouldFail;
    // Record number of calls made and last decoded args
    uint public calls;
    address[] public last_froms;
    address[] public last_tos;
    uint[] public last_vals;

    constructor(bool _shouldFail) {
        shouldFail = _shouldFail;
    }

    // This matches selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls += 1;
        last_froms.push(from);
        last_tos.push(to);
        last_vals.push(value);
        if (shouldFail) {
            revert("forced revert");
        }
        return true;
    }

    // helpers to expose arrays' lengths for test observation if needed
    function last_froms_length() external view returns (uint) { return last_froms.length; }
    function last_tos_length() external view returns (uint) { return last_tos.length; }
    function last_vals_length() external view returns (uint) { return last_vals.length; }
}
